// Turns dist/index.html into packages/core/src/ui-bundle.ts so the core
// package ships the UI as a single embedded string (no static file serving).
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(resolve(here, '../dist/index.html'), 'utf8');
if (!html.includes('<!--LUDIN_CONFIG-->')) throw new Error('index.html must contain <!--LUDIN_CONFIG-->');
const out = resolve(here, '../../core/src/ui-bundle.ts');
writeFileSync(
  out,
  `// Generated by @ludin-docs/ui build – do not edit.\nexport const UI_HTML = ${JSON.stringify(html)};\n`,
);
console.log(`ui bundle → ${out} (${(html.length / 1024).toFixed(1)} KB)`);
